// signedBy returns the v1 signature of body sent at ts with secret.
func signedBy(secret string, ts int64, body []byte) string {
	return webhooks.Sign(secret, []byte(fmt.Sprintf("%d.%s", ts, body)))
}

func TestVerify(t *testing.T) {
	now := time.Unix(1_800_000_000, 0)
	ts := now.Unix()
	body := []byte(`{"id":"evt_1"}`)
	cases := []struct {
		name    string
		header  string
		secrets []string
		tol     time.Duration
		want    error
	}{
		{"valid", fmt.Sprintf("t=%d,v1=%s", ts, signedBy("whsec_a", ts, body)), []string{"whsec_a"}, 0, nil},
		{"spaces, order and unknown keys", fmt.Sprintf(" v0=abc , v1=%s , t = %d ", signedBy("whsec_a", ts, body), ts), []string{"whsec_a"}, 0, nil},
		{"any of several v1 entries", fmt.Sprintf("t=%d,v1=%s,v1=%s", ts, signedBy("whsec_new", ts, body), signedBy("whsec_old", ts, body)), []string{"whsec_old"}, 0, nil},
		{"any of several secrets", fmt.Sprintf("t=%d,v1=%s", ts, signedBy("whsec_old", ts, body)), []string{"whsec_new", "whsec_old"}, 0, nil},
		{"exactly the default tolerance in the past", fmt.Sprintf("t=%d,v1=%s", ts-300, signedBy("whsec_a", ts-300, body)), []string{"whsec_a"}, 0, nil},
		{"exactly the default tolerance in the future", fmt.Sprintf("t=%d,v1=%s", ts+300, signedBy("whsec_a", ts+300, body)), []string{"whsec_a"}, 0, nil},
		{"past the default tolerance", fmt.Sprintf("t=%d,v1=%s", ts-301, signedBy("whsec_a", ts-301, body)), []string{"whsec_a"}, 0, webhooks.ErrTimestampTolerance},
		{"future beyond the default tolerance", fmt.Sprintf("t=%d,v1=%s", ts+301, signedBy("whsec_a", ts+301, body)), []string{"whsec_a"}, 0, webhooks.ErrTimestampTolerance},
		{"past a short tolerance", fmt.Sprintf("t=%d,v1=%s", ts-61, signedBy("whsec_a", ts-61, body)), []string{"whsec_a"}, time.Minute, webhooks.ErrTimestampTolerance},
		{"within a short tolerance", fmt.Sprintf("t=%d,v1=%s", ts-60, signedBy("whsec_a", ts-60, body)), []string{"whsec_a"}, time.Minute, nil},
		{"empty", "", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"blank", "  ", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"pair without =", fmt.Sprintf("t=%d,v1", ts), []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"empty pair", fmt.Sprintf("t=%d,,v1=%s", ts, signedBy("whsec_a", ts, body)), []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"timestamp not an integer", "t=soon,v1=abc", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"empty timestamp", "t=,v1=abc", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"malformed before an old timestamp", "t=1,v1", []string{"whsec_a"}, 0, webhooks.ErrMalformedHeader},
		{"no timestamp", fmt.Sprintf("v1=%s", signedBy("whsec_a", ts, body)), []string{"whsec_a"}, 0, webhooks.ErrNoTimestamp},
		{"no timestamp and no signature", "v0=abc", []string{"whsec_a"}, 0, webhooks.ErrNoTimestamp},
		{"no v1 entry", fmt.Sprintf("t=%d,v0=%s", ts, signedBy("whsec_a", ts, body)), []string{"whsec_a"}, 0, webhooks.ErrNoSignature},
		{"tolerance checked before the signature", fmt.Sprintf("t=%d", ts-600), []string{"whsec_a"}, 0, webhooks.ErrTimestampTolerance},
		{"wrong secret", fmt.Sprintf("t=%d,v1=%s", ts, signedBy("whsec_b", ts, body)), []string{"whsec_a"}, 0, webhooks.ErrSignatureMismatch},
		{"no secrets", fmt.Sprintf("t=%d,v1=%s", ts, signedBy("whsec_a", ts, body)), nil, 0, webhooks.ErrSignatureMismatch},
		{"signature of another timestamp", fmt.Sprintf("t=%d,v1=%s", ts, signedBy("whsec_a", ts+1, body)), []string{"whsec_a"}, 0, webhooks.ErrSignatureMismatch},
		{"empty v1 entry", fmt.Sprintf("t=%d,v1=", ts), []string{"whsec_a"}, 0, webhooks.ErrSignatureMismatch},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if err := webhooks.Verify(body, tc.header, tc.secrets, tc.tol, now); !errors.Is(err, tc.want) {
				t.Fatalf("Verify = %v, want %v", err, tc.want)
			}
		})
	}
	if err := webhooks.Verify([]byte(`{"id":"evt_2"}`), fmt.Sprintf("t=%d,v1=%s", ts, signedBy("whsec_a", ts, body)), []string{"whsec_a"}, 0, now); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("a changed body verified: %v", err)
	}
}

func TestSignatureHeader(t *testing.T) {
	now := time.Unix(1_800_000_000, 0)
	body := []byte(`{"id":"evt_1"}`)
	header := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, now, body)
	want := fmt.Sprintf("t=%d,v1=%s,v1=%s", now.Unix(), signedBy("whsec_new", now.Unix(), body), signedBy("whsec_old", now.Unix(), body))
	if header != want {
		t.Fatalf("SignatureHeader = %q, want %q", header, want)
	}
	for _, secret := range []string{"whsec_new", "whsec_old"} {
		if err := webhooks.Verify(body, header, []string{secret}, 0, now); err != nil {
			t.Fatalf("Verify with %s: %v", secret, err)
		}
	}
}

func TestSigningSecrets(t *testing.T) {
	rotated := time.Unix(1_800_000_000, 0)
	ep := store.WebhookEndpoint{Secret: "whsec_new", PreviousSecret: "whsec_old", SecretRotatedAt: rotated}
	for _, c := range []struct {
		at   time.Duration
		want []string
	}{
		{0, []string{"whsec_new", "whsec_old"}},
		{24*time.Hour - time.Second, []string{"whsec_new", "whsec_old"}},
		{24 * time.Hour, []string{"whsec_new"}},
	} {
		if got := webhooks.SigningSecrets(ep, rotated.Add(c.at)); !slices.Equal(got, c.want) {
			t.Fatalf("SigningSecrets after %v = %v, want %v", c.at, got, c.want)
		}
	}
	if got := webhooks.SigningSecrets(store.WebhookEndpoint{Secret: "whsec_new"}, rotated); !slices.Equal(got, []string{"whsec_new"}) {
		t.Fatalf("an endpoint never rotated: %v", got)
	}
}

func TestRotateSecret(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, e.Clock.Now())
	// send publishes an event, sends it and returns the request the endpoint received.
	send := func() apitest.Request {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("RunDue = %d, %v", n, err)
		}
		reqs := e.HTTP.Requests()
		return reqs[len(reqs)-1]
	}

	first, err := e.Webhooks.RotateSecret(e.Acme.ID, ep.ID)
	if err != nil {
		t.Fatal(err)
	}
	if first.Secret == "whsec_a" || !strings.HasPrefix(first.Secret, "whsec_") || len(first.Secret) != len("whsec_")+32 {
		t.Fatalf("new secret = %q", first.Secret)
	}
	rotatedAt := e.Clock.Now()
	req := send()
	header := req.Header.Get("Tally-Signature")
	if want := webhooks.SignatureHeader([]string{first.Secret, "whsec_a"}, rotatedAt, req.Body); header != want {
		t.Fatalf("header = %q, want %q", header, want)
	}
	if err := webhooks.Verify(req.Body, header, []string{"whsec_a"}, 0, rotatedAt); err != nil {
		t.Fatalf("the previous secret stopped working within 24 hours: %v", err)
	}

	e.Clock.Set(rotatedAt.Add(webhooks.PreviousSecretTTL - time.Second))
	if header := send().Header.Get("Tally-Signature"); strings.Count(header, "v1=") != 2 {
		t.Fatalf("header 23h59m59s after the rotation = %q, want two v1 entries", header)
	}

	e.Clock.Set(rotatedAt.Add(webhooks.PreviousSecretTTL))
	req = send()
	header = req.Header.Get("Tally-Signature")
	if want := webhooks.SignatureHeader([]string{first.Secret}, e.Clock.Now(), req.Body); header != want {
		t.Fatalf("header after 24 hours = %q, want only the new secret", header)
	}
	if err := webhooks.Verify(req.Body, header, []string{"whsec_a"}, 0, e.Clock.Now()); err == nil {
		t.Fatal("the previous secret still signed after 24 hours")
	}

	// A second rotation drops the oldest secret at once.
	second, err := e.Webhooks.RotateSecret(e.Acme.ID, ep.ID)
	if err != nil {
		t.Fatal(err)
	}
	req = send()
	header = req.Header.Get("Tally-Signature")
	if want := webhooks.SignatureHeader([]string{second.Secret, first.Secret}, e.Clock.Now(), req.Body); header != want {
		t.Fatalf("header after a second rotation = %q, want %q", header, want)
	}
	if err := webhooks.Verify(req.Body, header, []string{"whsec_a"}, 0, e.Clock.Now()); err == nil {
		t.Fatal("the secret before the first rotation still signed after a second rotation")
	}

	if _, err := e.Webhooks.RotateSecret(e.Acme.ID, "we_missing"); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("rotating a missing endpoint = %v", err)
	}
	if _, err := e.Webhooks.RotateSecret(e.Globex.ID, ep.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("rotating another organization's endpoint = %v", err)
	}
}

func TestRotateEndpointSecret(t *testing.T) {
	e := apitest.New(t)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	var rotated store.WebhookEndpoint
	e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &rotated)
	if rotated.ID != ep.ID || rotated.Secret == ep.Secret || !strings.HasPrefix(rotated.Secret, "whsec_") || len(rotated.Secret) != len("whsec_")+32 {
		t.Fatalf("rotated endpoint = %+v (was %+v)", rotated, ep)
	}
	if r := e.Do("POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("another organization rotated the secret: %s", r)
	}
	if r := e.Do("POST", "/v1/webhook-endpoints/we_missing/rotate-secret", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("missing endpoint: %s", r)
	}
}

